mapper.update:
UPDATE comment
SET
    content = #{content},
    updated_at = NOW()
WHERE comment_id = #{commentId}
    AND member_id = #{memberId}

mapper.delete:
DELETE FROM comment
WHERE comment_id = #{commentId}
    AND member_id = #{memberId}

mapper.select:
SELECT COUNT(*)
FROM comment
WHERE board_id = #{boardId}

SELECT c.comment_id, c.board_id, c.member_id, m.nickname, c.content, c.created_at, c.updated_at FROM comment c JOIN member m ON c.member_id = m.member_id WHERE c.board_id = #{boardId}
ORDER BY c.created_at
LIMIT #{size} OFFSET #{offset}
